<?php require __DIR__.'/layout.php';$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT * FROM posts WHERE id=? AND published=1");$st->execute([$id]);$n=$st->fetch();if(!$n){http_response_code(404);exit('Notícia não encontrada.');}site_header($n['title']);?>
<main id="conteudo-principal" class="article-page"><?php if($n['cover_path']):?><img class="article-cover" src="<?=e($n['cover_path'])?>" alt="Capa da notícia <?=e($n['title'])?>"><?php endif;?><small><?php $nts=strtotime((string)$n['created_at']);?><?=e($nts?date('d/m/Y',$nts):'')?></small><h1><?=e($n['title'])?></h1><p class="lead"><?=e($n['summary'])?></p><div class="article-content"><?=nl2br(e($n['content']))?></div></main><?php site_footer();?>
